      en: ["Easternmost point of Oman and the Arabian Peninsula", "Largest nesting site for Green Sea Turtles in the Indian Ocean", "Established as a protected reserve in 1996", "Over 30.000 turtles visit the beach annually", "Features a dedicated scientific research center", "Archaeological evidence shows settlement dating back to 3000 BC"],
      es: ["Fundada en el año 1996.", "Anualmente anidan aquí unas 20.000 tortugas verdes.", "La temporada principal de anidación es de junio a septiembre.", "Se ofrecen visitas nocturnas para observar el desove.", "La reserva protege una franja costera de 45 km de largo.", "Alberga un museo interactivo y un centro de investigación.", "Las tortugas ponen entre 100 y 120 huevos cada vez."],
      pt: ["Fundada no ano de 1996.", "Anualmente, cerca de 20.000 tartarugas-verdes desovam aqui.", "A principal época de desova é de junho a setembro.", "São oferecidas visitas noturnas para observar a desova.", "A reserva protege uma faixa costeira de 45 km de comprimento.", "Abriga um museu interativo e um centro de investigação.", "As tartarugas depositam entre 100 e 120 ovos de cada vez."],
      fr: ["Fondée en 1996.", "Environ 20 000 tortues vertes y nichent chaque année.", "La principale saison de nidification s'étend de juin à septembre.", "Des visites nocturnes sont proposées pour observer la nidification.", "La réserve protège une bande côtière de 45 km de long.", "Abrite un musée interactif et un centre de recherche.", "Les tortues pondent entre 100 et 120 œufs à chaque fois."],
