      es: ["Inaugurado en 1985", "Alberga un jardín japonés", "Grandes áreas de recreo", "Centro de muchos festivales locales"],
      pt: ["Inaugurado em 1985", "Acolhe um jardim japonês", "Grandes áreas de lazer", "Centro de muitos festivais locais"],
      fr: ["Ouvert en 1985", "Abrite un jardin japonais", "Grandes surfaces de loisirs", "Centre de nombreux festivals locaux"],
