    descriptionAdvanced: {
      de: "Der Al Naseem Park war die erste große Parkanlage in Oman und wurde 1985 anlässlich des 15. Nationalfeiertags des Sultanats eröffnet. Er befindet sich in der Nähe von Seeb und Barka und erstreckt sich über eine Fläche von etwa 750.000 Quadratmetern. Ein herausragendes Merkmal des Parks ist der japanische Garten, der als Geschenk der japanischen Regierung zum 20. Thronjubiläum von Sultan Qaboos angelegt wurde. Die Anlage umfasst zudem weitläufige Spielbereiche, Sportplätze und ein kleines Aquarium, was ihn zu einem beliebten Ziel für Familien aus der gesamten Batinah-Region macht. Während des Muscat Festivals verwandelt sich der Park in ein Zentrum für traditionelles Handwerk und internationale Ausstellungen. Die Flora besteht hauptsächlich aus schattenspendenden Bäumen und saisonalen Blumenbeeten, die sorgfältig gepflegt werden, um der Hitze der Küstenebene standzuhalten. Er gilt als wegweisendes Projekt für die urbane Begrünung in Oman.",
      hu: "Az Al Naseem Park Omán első nagy közparkja volt, amelyet 1985-ben nyitottak meg a szultanátus 15. nemzeti ünnepe alkalmából. A park Seeb és Barka közelében található, és körülbelül 750 000 négyzetméteres területen fekszik. A létesítmény egyik kiemelkedő jellemzője a japánkert, amely a japán kormány ajándékaként készült Qaboos szultán trónra lépésének 20. évfordulójára. Az alaprajz tágas játszótereket, sportpályákat és egy kis akváriumot is magában foglal, így a Batinah-régió családjainak kedvelt célpontja. A Maszkat Fesztivál ideje alatt a park a hagyományos kézművesség és nemzetközi kiállítások központjává válik. A flórát főként árnyékot adó fák és szezonális virágágyások alkotják, amelyeket gondosan tartanak fenn a parti síkság hőségében. Az Al Naseem mérföldkőnek számít Omán városi zöldítési programjaiban.",
      ro: "Parcul Al Naseem a fost prima mare zonă de agrement din Oman, fiind inaugurat în 1985 cu ocazia celei de-a 15-a aniversări a Zilei Naționale a Sultanatului. Situat în proximitatea localităților Seeb și Barka, parcul acoperă o suprafață de aproximativ 750.000 de metri pătrați. O trăsătură distinctivă a parcului este grădina japoneză, creată ca dar din partea guvernului Japoniei pentru a marca 20 de ani de domnie ai Sultanului Qaboos. Complexul include, de asemenea, zone extinse de joacă, terenuri de sport și un mic acvariu, fiind o destinație populară pentru familiile din regiunea Batinah. În timpul Festivalului de la Muscat, parcul devine un centru pentru meșteșuguri tradiționale și expoziții internaționale. Vegetația este compusă în principal din arbori care oferă umbră și straturi de flori sezoniere, îngrijite riguros pentru a rezista căldurii din câmpia de coastă. Este considerat un proiect pionier pentru urbanismul verde din Oman.",
      en: "Al Naseem Park was the first major public park established in Oman, opening its gates in 1985 to mark the Sultanate's 15th National Day. Located near the border of Seeb and Barka, the park spans an area of approximately 750.000 square meters. A standout feature of the facility is the authentic Japanese Garden, which was gifted by the Japanese government to commemorate the 20th anniversary of Sultan Qaboos's accession. The grounds also feature extensive playgrounds, sports courts, and a small aquarium, making it a premier destination for families across the Batinah region. During the Muscat Festival, the park serves as a major hub for traditional crafts and international trade exhibitions. The flora consists largely of shade-giving trees and seasonal flower beds meticulously maintained to withstand the coastal plain's heat. It remains a landmark project in Oman's history of urban greening and public recreation.",
      es: "El Parque Al Naseem, situado cerca de Barka, es uno de los parques públicos más antiguos y grandes de Omán. Es especialmente popular entre las familias, que aprovechan las amplias zonas verdes, los parques infantiles y las instalaciones recreativas. Una de las atracciones principales es el tren en miniatura que recorre el parque y es muy apreciado por los niños. El parque también cuenta con un pequeño zoológico, un lago y jardines con una gran variedad de plantas. Durante el invierno y en los días festivos, el parque suele ser escenario de festivales y eventos. Su ubicación fuera de Mascate lo convierte en un destino popular para excursiones de fin de semana para los residentes de la región de la capital.",
      pt: "O Parque Al Naseem, localizado perto de Barka, é um dos parques públicos mais antigos e maiores de Omã. É especialmente popular entre as famílias, que aproveitam as amplas áreas verdes, os parques infantis e as instalações de lazer. Uma das principais atrações é o comboio em miniatura que percorre o parque e é muito apreciado pelas crianças. O parque também possui um pequeno jardim zoológico, um lago e jardins com uma variedade de plantas. Durante o inverno e em feriados, o parque é frequentemente palco de festivais e eventos. A sua localização fora de Mascate torna-o num destino popular para excursões de fim de semana para os residentes da região da capital.",
      fr: "Le parc Al Naseem, situé près de Barka, est l'un des plus anciens et des plus grands parcs publics d'Oman. Il est particulièrement apprécié des familles qui profitent des vastes espaces verts, des aires de jeux et des installations de loisirs. L'une des attractions principales est le train miniature qui parcourt le parc et qui est très populaire auprès des enfants. Le parc dispose également d'un petit zoo, d'un lac et de jardins avec une grande variété de plantes. Pendant l'hiver et les jours fériés, le parc est souvent le théâtre de festivals et d'événements. Sa situation à l'extérieur de Mascate en fait une destination d'excursion populaire le week-end pour les habitants de la région de la capitale.",
    },
