      fr: ["L'un des plus anciens parcs de la région de la capitale.", "Situé près de la ville de Barka, à l'ouest de Mascate.", "Dispose d'un train miniature très apprécié.", "Abrite un petit zoo avec des animaux indigènes et exotiques.", "Grand lac artificiel pour faire du bateau.", "Des célébrations spéciales y ont lieu pendant la fête de l'Aïd.", "Le parc est connu pour ses plates-bandes de fleurs variées."],
