      es: ["Situado en la costa, en el corazón de la antigua Mascate.", "Ofrece una vista magnífica del Golfo de Omán.", "Una piscina de marea se llena con la marea alta y sirve como piscina infantil.", "Se encuentra cerca del Palacio Al Alam y del Museo Nacional.", "Un parque tranquilo y menos concurrido.", "Equipado con parques infantiles y zonas de picnic.", "Ideal para observar la puesta de sol sobre el mar."],
      pt: ["Localizado na costa, no coração da antiga Mascate.", "Oferece uma vista magnífica sobre o Golfo de Omã.", "Uma piscina de maré enche-se na maré alta e serve como piscina infantil.", "Encontra-se perto do Palácio Al Alam e do Museu Nacional.", "Um parque tranquilo e menos concorrido.", "Equipado com parques infantis e áreas de piquenique.", "Ideal para observar o pôr do sol sobre o mar."],
