      es: ["Uno de los principales escenarios del Festival de Mascate.", "Cuenta con una réplica de una aldea de patrimonio omaní.", "Situado en el Wilayat Al Amerat, al sureste de Mascate.", "Rodeado por el espectacular paisaje de las montañas Al Hajar.", "Ofrece numerosas atracciones y juegos durante los festivales.", "Grandes áreas libres para deportes y picnics.", "El parque ha sido ampliado considerablemente en los últimos años."],
      pt: ["Um dos principais locais de realização do Festival de Mascate.", "Possui uma réplica de uma aldeia de património omanense.", "Localizado no Wilayat Al Amerat, a sudeste de Mascate.", "Rodeado pelo cenário dramático das montanhas Al Hajar.", "Oferece inúmeros carrosséis e jogos durante os festivais.", "Grandes áreas livres para desporto e piqueniques.", "O parque foi significativamente ampliado nos últimos anos."],
