      ro: ["Cultivarea trandafirului de Damasc (Rosa damascena).", "Sezonul de înflorire este de la sfârșitul lunii martie până la începutul lunii mai.", "Apa de trandafiri este produsă în distilerii tradiționale.", "Terasele sunt irigate prin sisteme antice falaj.", "Zona este cunoscută și pentru cultivarea rodiilor.", "Jebel Akhdar înseamnă 'Muntele Verde'.", "Clima răcoroasă permite cultivarea fructelor și a trandafirilor."],
      en: ["Cultivation of the Damask rose (Rosa damascena).", "The blooming season is from late March to early May.", "Rosewater is produced in traditional distilleries.", "The terraces are irrigated by ancient falaj systems.", "The area is also famous for growing pomegranates.", "Jebel Akhdar means 'The Green Mountain'.", "The cool climate allows for the cultivation of fruits and roses."],
