      pt: ["Cultivo da rosa de Damasco (Rosa damascena).", "A época de floração é do final de março ao início de maio.", "A água de rosas é produzida em destilarias tradicionais.", "As esplanadas são irrigadas por sistemas Falaj antigos.", "A área também é conhecida pelo cultivo de romãs.", "Jebel Akhdar significa 'A Montanha Verde'.", "O clima fresco permite o cultivo de frutas e rosas."],
      fr: ["Culture de la rose de Damas (Rosa damascena).", "La période de floraison s'étend de fin mars à début mai.", "L'eau de rose est fabriquée dans des distilleries traditionnelles.", "Les terrasses sont irriguées par d'anciens systèmes Falaj.", "La région est également connue pour la culture des grenades.", "Jebel Akhdar signifie 'La Montagne Verte'.", "Le climat frais permet la culture de fruits et de roses."],
