      es: ["El parque acuático más grande de Dhofar", "Muchos toboganes de agua", "Piscina de olas", "Parte del complejo Hawana Resort"],
      pt: ["O maior parque aquático de Dhofar", "Muitos escorregas aquáticos", "Piscina de ondas", "Parte do complexo Hawana Resort"],
