    descriptionAdvanced: {
      de: "Der Hawana Aqua Park in der Nähe von Salalah ist der erste Wasserpark in der Region Dhofar. Er ist Teil des Hawana Salalah Resorts, aber auch für die Öffentlichkeit zugänglich. Der Park bietet eine Vielzahl von Wasserrutschen, einen Strömungskanal, ein Wellenbad und spezielle Spielbereiche für Kinder. Mit seinen Rutschen, die von sanft bis extrem reichen, spricht er alle Altersgruppen und Adrenalinlevel an. Die Gestaltung des Parks ist von der lokalen Kultur inspiriert und bietet eine unterhaltsame und erfrischende Abwechslung, besonders während der heißen Sommermonate. Neben den Wasserattraktionen gibt es Restaurants, Snackbars und Liegebereiche zum Entspannen. Es ist ein beliebtes Ziel für Familien und Touristen, die einen Tag voller Wasserspaß in der wunderschönen Umgebung von Salalah verbringen möchten.",
      hu: "A Hawana Aqua Park, Salalah közelében, a Dhofar régió első víziparkja. A Hawana Salalah üdülőközpont része, de a nagyközönség számára is nyitva áll. A park különféle vízi csúszdákat, egy lassú folyót, egy hullámmedencét és különleges játszótereket kínál a gyermekek számára. A szelídtől az extrémig terjedő csúszdáival minden korosztályt és adrenalin szintet megszólít. A park kialakítását a helyi kultúra ihlette, és szórakoztató, frissítő kikapcsolódást nyújt, különösen a forró nyári hónapokban. A vízi attrakciók mellett éttermek, büfék és pihenőhelyek is találhatók. Népszerű célpont a családok és a turisták számára, akik egy napot tele vízi mókával szeretnének eltölteni Salalah gyönyörű környezetében.",
      ro: "Parcul acvatic Hawana, situat lângă Salalah, este primul parc acvatic din regiunea Dhofar. Face parte din stațiunea Hawana Salalah, dar este deschis și publicului larg. Parcul oferă o varietate de tobogane cu apă, un râu leneș, o piscină cu valuri și zone de joacă speciale pentru copii. Cu tobogane care variază de la blânde la extreme, se adresează tuturor vârstelor și nivelurilor de adrenalină. Designul parcului este inspirat de cultura locală și oferă o distracție răcoritoare, în special în timpul lunilor fierbinți de vară. Pe lângă atracțiile acvatice, există restaurante, snack-baruri și zone de relaxare. Este o destinație populară pentru familii și turiști care doresc să petreacă o zi plină de distracție acvatică în împrejurimile frumoase ale orașului Salalah.",
      en: "Hawana Aqua Park, located near Salalah, is the first water park in the Dhofar region. It is part of the Hawana Salalah resort but is also open to the general public. The park offers a variety of water slides, a lazy river, a wave pool, and special play areas for children. With slides ranging from gentle to extreme, it caters to all ages and adrenaline levels. The park's design is inspired by local culture and provides a fun and refreshing escape, especially during the hot summer months. In addition to the water attractions, there are restaurants, snack bars, and lounge areas for relaxation. It's a popular destination for families and tourists looking to spend a day of water-filled fun in the beautiful surroundings of Salalah.",
      es: "El Hawana Aqua Park, cerca de Salalah, es el primer parque acuático de la región de Dhofar. Forma parte del complejo Hawana Salalah Resort, pero también está abierto al público. El parque ofrece una variedad de toboganes de agua, un río lento, una piscina de olas y áreas de juego especiales para niños. Con toboganes que van desde suaves hasta extremos, atrae a todas las edades y niveles de adrenalina. El diseño del parque está inspirado en la cultura local y ofrece una alternativa divertida y refrescante, especialmente durante los calurosos meses de verano. Además de las atracciones acuáticas, hay restaurantes, cafeterías y zonas de descanso para relajarse. Es un destino popular para familias y turistas que desean pasar un día de diversión acuática en el hermoso entorno de Salalah.",
      pt: "O Hawana Aqua Park, perto de Salalah, é o primeiro parque aquático da região de Dhofar. Faz parte do Hawana Salalah Resort, mas também está aberto ao público. O parque oferece uma variedade de escorregas aquáticos, um rio lento, uma piscina de ondas e áreas de lazer especiais para crianças. Com escorregas que variam de suaves a extremos, atrai todas as idades e níveis de adrenalina. O design do parque é inspirado na cultura local e oferece uma alternativa divertida e refrescante, especialmente durante os meses quentes de verão. Além das atrações aquáticas, existem restaurantes, snack-bars e áreas de repouso para relaxar. É um destino popular para famílias e turistas que desejam passar um dia de diversão aquática na bela envolvente de Salalah.",
      fr: "Le Hawana Aqua Park, situé près de Salalah, est le premier parc aquatique de la région du Dhofar. Il fait partie du complexe Hawana Salalah Resort, mais est également ouvert au public. Le parc propose une variété de toboggans aquatiques, une rivière lente, une piscine à vagues et des aires de jeux spéciales pour les enfants. Avec ses toboggans allant de doux à extrêmes, il s'adresse à tous les âges et à tous les niveaux d'adrénaline. La conception du parc s'inspire de la culture locale et offre une alternative amusante et rafraîchissante, surtout pendant les mois d'été chauds. Outre les attractions aquatiques, on y trouve des restaurants, des snacks et des espaces de détente. C'est une destination populaire pour les familles et les touristes qui souhaitent passer une journée de divertissement aquatique dans le cadre magnifique de Salalah.",
    },
