      ro: ["Primul parc acvatic din regiunea Dhofar.", "Parte a complexului turistic integrat Hawana Salalah.", "Inaugurat în 2018.", "Oferă tobogane, o piscină cu valuri și un râu leneș.", "Suprafață totală de 65.000 de metri pătrați.", "Dispune de o zonă de joacă dedicată copiilor 'Kiddie Pools'.", "O evadare binevenită de la căldura regiunii."],
      en: ["The first water park in the Dhofar region.", "Part of the Hawana Salalah integrated tourism complex.", "Opened in 2018.", "Features slides, a wave pool, and a lazy river.", "Total area of 65,000 square meters.", "Has a dedicated kids' play area 'Kiddie Pools'.", "A welcome escape from the region's heat."],
      es: ["El primer parque acuático de la región de Dhofar.", "Parte del complejo turístico integrado Hawana Salalah.", "Inaugurado en el año 2018.", "Ofrece toboganes, una piscina de olas y un río lento.", "Superficie total de 65.000 metros cuadrados.", "Cuenta con su propia zona de juegos infantiles 'Kiddie Pools'.", "Un alivio bienvenido del calor de la región."],
      pt: ["O primeiro parque aquático da região de Dhofar.", "Parte do complexo turístico integrado Hawana Salalah.", "Inaugurado no ano de 2018.", "Oferece escorregas, uma piscina de ondas e um rio lento.", "Área total de 65.000 metros quadrados.", "Possui a sua própria área de lazer infantil 'Kiddie Pools'.", "Um refresco bem-vindo ao calor da região."],
      fr: ["Le premier parc aquatique de la région du Dhofar.", "Fait partie du complexe touristique intégré Hawana Salalah.", "Inauguré en 2018.", "Propose des toboggans, une piscine à vagues et une rivière lente.", "Superficie totale de 65 000 mètres carrés.", "Dispose de sa propre aire de jeux pour enfants « Kiddie Pools ».", "Un rafraîchissement bienvenu face à la chaleur de la région."],
